WHEN EXISTS(SELECT 1 FROM lk_artifacts a JOIN lk_legal_holds h ON h.agreement_id=a.agreement_id WHERE a.id=OLD.artifact_id AND h.active=1)
BEGIN SELECT RAISE(ABORT,'LOCKET_LEGAL_HOLD'); END;

